#include "f3_mpo_core.hpp"
#include <map>
#include <random>
using Small=std::vector<unsigned char>;
using V9=std::array<int,9>;
bool nilpotent_certificate(V9 const&U,V9 const&V){int B[3][3]{},C[3][3]{};for(int i=0;i<3;i++)for(int j=0;j<3;j++){for(int k=0;k<3;k++){B[i][j]+=U[3*i+k]*V[3*k+j];C[i][j]+=V[3*j+k]*U[3*k+i];}B[i][j]%=3;C[i][j]%=3;}if((B[0][0]+B[1][1]+B[2][2])%3)return false;int e2=0;for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)e2+=B[i][i]*B[j][j]-B[i][j]*B[j][i];if(mod(e2))return false;
int M[3][3][4]{};for(int i=0;i<3;i++)for(int j=0;j<3;j++){M[i][j][0]=mod(B[i][j]+C[i][j]);M[i][j][1]=mod(B[i][j]-C[i][j]);M[i][j][2]=B[i][j];M[i][j][3]=i==j;}int det[10]{};int perms[6][4]={{0,1,2,1},{0,2,1,-1},{1,0,2,-1},{1,2,0,1},{2,0,1,1},{2,1,0,-1}};for(auto&p:perms)for(int i=0;i<4;i++)for(int j=0;j<4;j++)for(int k=0;k<4;k++)det[i+j+k]+=p[3]*M[0][p[0]][i]*M[1][p[1]][j]*M[2][p[2]][k];for(int k=0;k<9;k++)if(mod(det[k]))return false;return mod(det[9])==1;}
std::vector<GM> candidate(V9 const&U,V9 const&V,int&degree){constexpr int q=3,D=3,n=27;Small B(n*n),N(n*n);for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int a=0;a<D;a++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int b=0;b<D;b++){int r=(x*q+y)*D+a,c=(u*q+v)*D+b;if(y==v)B[r*n+c]=mod(int(x==b&&a==u)+U[3*x+a]*V[3*b+u]);}
for(int r=0;r<n;r++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int b=0;b<D;b++){int c=(u*q+v)*D+b,ce=(v*q+u)*D+b;N[r*n+c]=mod(int(r==c)-B[r*n+ce]);}
std::vector<GM>K(q*q*q*q,GM(D*D));Small C=B;degree=0;for(int k=0;k<=27;k++){bool nonzero=false;for(auto x:C)nonzero|=x!=0;if(!nonzero){degree=k-1;break;}if(k==27)throw std::runtime_error("nilpotence certificate failed");for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int a=0;a<D;a++)for(int b=0;b<D;b++){int r=(x*q+y)*D+a,c=(u*q+v)*D+b,co=C[r*n+c];auto&t=K[((x*q+y)*q+u)*q+v][D*a+b];if(co==1)t.a|=uint64_t(1)<<k;if(co==2)t.b|=uint64_t(1)<<k;}Small next(n*n);for(int i=0;i<n;i++)for(int j=0;j<n;j++){int value=0;for(int h=0;h<n;h++)value+=N[i*n+h]*C[h*n+j];next[i*n+j]=value%3;}C=std::move(next);}
for(int x=0;x<q;x++)for(int y=0;y<q;y++)for(int u=0;u<q;u++)for(int v=0;v<q;v++)for(int a=0;a<D;a++)for(int b=0;b<D;b++){T f=K[((x*q+y)*q+u)*q+v][D*a+b];if((std::popcount(f.a)+2*std::popcount(f.b))%3!=(x==v&&y==u&&a==b))throw std::runtime_error("endpoint");}return K;}
int main(int argc,char**argv){int trials=argc>1?std::stoi(argv[1]):200000;std::string path=argc>2?argv[2]:"";J=64;PMASK=~U(0);std::mt19937_64 rng(633981301);auto start=std::chrono::steady_clock::now();int survivors=0,precisionfail=0;double best=1e300,bestS=0;V9 bestU{},bestV{};int bestDegree=0,bi=0,bj=0;std::vector<int>bestD,bestNu;std::map<int,int>degrees;
for(int trial=0;trial<trials;trial++){V9 a{},b{};int pivot=-1;while(pivot<0)for(int i=0;i<9;i++){a[i]=rng()%3;if(a[i])pivot=i;}int dot=0;for(int i=0;i<9;i++)if(i!=pivot){b[i]=rng()%3;dot+=a[i]*b[i];}b[pivot]=mod(-dot*a[pivot]);bool bn=false;for(auto x:b)bn|=x!=0;if(!bn)continue;if(!nilpotent_certificate(a,b))continue;survivors++;int L;auto K=candidate(a,b,L);degrees[L]++;std::array<std::vector<int>,4>ds,ns;try{for(int cut=0;cut<2;cut++)for(int side=0;side<2;side++){int i=2*cut+side;ns[i]=smith(gflatten(K,3,3,cut,side,L,false),9);ds[i]=smith(gflatten(K,3,3,cut,side,L,true),9);for(auto&v:ds[i])v=L-v;}}catch(std::runtime_error&e){precisionfail++;continue;}
for(int cut=0;cut<2;cut++)for(int s1=0;s1<2;s1++)for(int s2=0;s2<2;s2++){int i=2*cut+s1,j=2*(1-cut)+s2;double lo=0,hi=8;for(int k=0;k<70;k++){double x=(2*lo+hi)/3,y=(lo+2*hi)/3;if(objective(ds[i],ns[j],x)<objective(ds[i],ns[j],y))hi=y;else lo=x;}double t=(lo+hi)/2,value=objective(ds[i],ns[j],t);if(value<best-1e-9){best=value;bestS=std::exp(t);bestU=a;bestV=b;bestDegree=L;bestD=ds[i];bestNu=ns[j];bi=i;bj=j;std::cout<<"newbest trial "<<trial<<" survivors "<<survivors<<" degree "<<L<<" B "<<std::setprecision(15)<<best<<" rho "<<std::log(best)/(4*std::log(3))<<std::endl;}}
if(survivors%500==0)std::cout<<"trial "<<trial<<" survivors "<<survivors<<" seconds "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<std::endl;}
auto emit=[&](std::ostream&o){o<<"{\"family\":\"ternary_rank_one_swap_resolvents\",\"field\":3,\"q\":3,\"auxiliary\":3,\"random_seed\":633981301,\"trials\":"<<trials<<",\"nilpotent_survivors\":"<<survivors<<",\"precision_failures\":"<<precisionfail<<",\"best_B\":"<<std::setprecision(16)<<best<<",\"best_s\":"<<bestS<<",\"rho\":"<<std::log(best)/(4*std::log(3))<<",\"degree\":"<<bestDegree<<",\"degree_cut_side\":"<<bi<<",\"order_cut_side\":"<<bj<<",\"U\":[";for(int i=0;i<9;i++)o<<(i?",":"")<<bestU[i];o<<"],\"V\":[";for(int i=0;i<9;i++)o<<(i?",":"")<<bestV[i];o<<"],\"d\":[";for(size_t i=0;i<bestD.size();i++)o<<(i?",":"")<<bestD[i];o<<"],\"nu\":[";for(size_t i=0;i<bestNu.size();i++)o<<(i?",":"")<<bestNu[i];o<<"],\"degree_counts\":{";int i=0;for(auto [L,c]:degrees)o<<(i++?",":"")<<"\""<<L<<"\":"<<c;o<<"},\"seconds\":"<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<"}";};emit(std::cout);std::cout<<std::endl;if(!path.empty()){std::ofstream out(path);emit(out);out<<std::endl;}}
